 15	
 16	export class OrderRepository {
 17	  findByUser(userId) {
 18	    return new Promise((resolve, reject) => {
 19	      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
 20	        (err, rows) => (err ? reject(err) : resolve(rows)));
 21	    });
 22	  }
 23	
 24	  findPaid() {
 25	    return new Promise((resolve, reject) => {
 26	      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
 27	        (err, rows) => (err ? reject(err) : resolve(rows)));
 28	    });
 29	  }
 30	}
