 32	
 33	// Callback-style database access. Chapter 5 migrates this to a PaymentRepository
 34	// the reader adds, which is the part of the exercise with no worked answer.
 35	export function findPaymentsForOrder(orderId, callback) {
 36	  query('payments', (p) => p.order_id === orderId, callback);
 37	}
 38	
 39	export function uncapturedTotalCents(callback) {
 40	  query('payments', (p) => p.captured === false, (err, rows) => {
 41	    if (err) return callback(err);
 42	    callback(null, rows.reduce((sum, p) => sum + p.amount_cents, 0));
 43	  });
 44	}
 45	// A router with no framework, so the project has an HTTP surface to survey
 46	// in Chapter 1's rate-limiting example without an Express dependency.
 47	import { listActiveUsers, findUser } from '../services/user-service.js';
 48	import { listOrdersForUser, totalPaidCents } from '../services/order-service.js';
 49	import { uncapturedTotalCents } from '../services/payment-service.js';
 50	
 51	export const routes = [
 52	  { method: 'GET', path: '/users', handler: (req, cb) => listActiveUsers(cb) },
 53	  { method: 'GET', path: '/users/:id', handler: (req, cb) => findUser(Number(req.params.id), cb) },
 54	  { method: 'GET', path: '/users/:id/orders', handler: (req, cb) => listOrdersForUser(Number(req.params.id), cb) },
 55	  { method: 'GET', path: '/reports/paid-total', handler: (req, cb) => totalPaidCents(cb) },
 56	  { method: 'GET', path: '/reports/uncaptured-total', handler: (req, cb) => uncapturedTotalCents(cb) },
 57	];
 58	
 59	export function listEndpoints() {
 60	  return routes.map((r) => `${r.method} ${r.path}`);
 61	}
 62	// A deliberately tiny in-memory database with a callback API.
 63	// The callback style is the point: Chapter 5 migrates the service layer off it.
 64	
 65	const tables = {
 66	  users: [
 67	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
 68	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
 69	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
 70	  ],
 71	  orders: [
 72	    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
 73	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
 74	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
 75	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
 76	  ],
 77	  payments: [
 78	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
 79	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
 80	  ],
 81	};
 82	
 83	export function reset() {
 84	  tables.users[2].deleted_at = '2026-01-04';
 85	  tables.orders.forEach((o) => { o.deleted_at = null; });
 86	}
 87	
 88	// Old-style callback query. Accepts a table name and a predicate.
 89	export function query(table, predicate, callback) {
 90	  setImmediate(() => {
 91	    const rows = tables[table];
 92	    if (!rows) return callback(new Error(`no such table: ${table}`));
 93	    try {
 94	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
 95	    } catch (err) {
 96	      callback(err);
 97	    }
 98	  });
 99	}
100	
101	export function update(table, id, patch, callback) {
102	  setImmediate(() => {
103	    const row = (tables[table] || []).find((r) => r.id === id);
104	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
105	    Object.assign(row, patch);
106	    callback(null, { ...row });
107	  });
108	}

